10	
11	#include "rope_aclnn_runner.h"
12	#include <aclnn/opdev/op_errno.h>
13	#include "atb/utils/aclnn_util.h"
14	#include "atb/utils/log.h"
15	#include "atbops/params/params.h"
16	#include "atb/utils/operation_register.h"
17	#include "atb/utils/tensor_util.h"
18	#include "acl/acl.h"
19	namespace atb {
20	static const uint32_t ROPE_IN_NUM = 4;
21	static const uint32_t ROPE_OUT_NUM = 2;
22	static const uint32_t ROPE_QUERY_INDEX = 0;
23	static const uint32_t ROPE_KEY_INDEX = 1;
24	static const uint32_t ROPE_COS_INDEX = 2;
25	static const uint32_t ROPE_SIN_INDEX = 3;
26	static const uint32_t ROPE_SEQLEN_INDEX = 4;
27	static const uint32_t ROTARY_COEFF_HALF = 2;
28	static const uint32_t ROTARY_COEFF_QUARTER = 4;
29	static const uint32_t ACLNN_BSND_DIM_NUM = 4;
30	static const uint32_t ACLNN_TND_DIM_NUM = 3;
31	static const uint32_t ATB_TND_DIM_NUM = 2;
32	static const uint32_t DIM_B = 0;
33	static const uint32_t DIM_S = 1;
34	static const uint32_t DIM_N = 2;
35	static const uint32_t DIM_D = 3;
36	static const uint32_t DIM_ONE = 1;
37	static const uint32_t COS_SIN_NUM = 2;
38	
39	enum class RotaryLayout : int {
40	    BSND = 1,
41	    SBND = 2,
42	    BNSD = 3,
43	    TND = 4,
44	};
45	
46	aclnnGetWorkspaceSizeFuncPtr RopeAclnnRunner::aclnnGetWorkspaceSizeFunc_ = nullptr;
47	aclnnExecuteFuncPtr RopeAclnnRunner::aclnnExecuteFunc_ = nullptr;
48	
49	RopeAclnnRunner::RopeAclnnRunner(const infer::RopeParam &param)
50	    : AclnnRunner("RopeAclnnRunner"), param_(param)
51	{
52	    ATB_LOG(INFO) << GetLogPrefix() << "RopeAclnnRunner::RopeAclnnRunner called";
53	}
54	
55	RopeAclnnRunner::~RopeAclnnRunner() {}
56	
57	Status RopeAclnnRunner::LoadMethod()
58	{
59	    ATB_LOG(INFO) << "RopeAclnnRunner LoadMethod";
60	    if (RopeAclnnRunner::aclnnGetWorkspaceSizeFunc_ != nullptr &&
61	        RopeAclnnRunner::aclnnExecuteFunc_ != nullptr) {
62	        return NO_ERROR;
63	    }
64	    Status status = LoadFromSharedObjectFile("aclnnApplyRotaryPosEmbV2GetWorkspaceSize", "aclnnApplyRotaryPosEmbV2",
65	                                             RopeAclnnRunner::aclnnGetWorkspaceSizeFunc_,
66	                                             RopeAclnnRunner::aclnnExecuteFunc_);
67	    return status;
68	}
69	
70	Status RopeAclnnRunner::BuildAclnnVariantPack(const RunnerVariantPack &runnerVariantPack)
71	{
72	    ATB_LOG(INFO) << GetLogPrefix() << "BuildAclnnVariantPack";
73	    ATB_LOG(INFO) << GetLogPrefix() << "variantPack: " << runnerVariantPack.ToString();
74	    this->atbVariantPack_ = runnerVariantPack;
75	    this->aclnnVariantPack_.aclInTensors.reserve(ROPE_IN_NUM);
76	    this->aclnnVariantPack_.aclInTensors.resize(ROPE_IN_NUM);
77	    this->aclnnVariantPack_.aclOutTensors.reserve(ROPE_OUT_NUM);
78	    this->aclnnVariantPack_.aclOutTensors.resize(ROPE_OUT_NUM);
79	    Status ret = NO_ERROR;
80	    bool isBSND4D = runnerVariantPack.inTensors.at(ROPE_QUERY_INDEX).desc.shape.dimNum == ACLNN_BSND_DIM_NUM;
81	    int64_t headDim = runnerVariantPack.inTensors.at(ROPE_COS_INDEX).desc.shape.dims[1]; // 1: headDim dim
82	
83	    //key and query reshape
84	    for (size_t i = 0; i < ROPE_IN_NUM - COS_SIN_NUM; ++i) {
85	        ATB_LOG(INFO) << GetLogPrefix() << "RopeAclnnRunner::BuildAclnnVariantPack inTensor index: " << i;
86	        std::shared_ptr<AclNNTensor> aclnnTensorPtr = std::make_shared<AclNNTensor>();
87	        atb::Tensor atbTensor = runnerVariantPack.inTensors.at(i);
88	        if (!isBSND4D) { // 2: [ntoken, hiddenSize]
89	            // [ntoken, hiddenSize] -> [ntoken, headNum, headDim]
90	            atbTensor.desc.shape.dimNum = ACLNN_TND_DIM_NUM; // tnd: [ntoken, headDim, headDim]
91	            atbTensor.desc.shape.dims[2] = headDim; // 2: d
92	            atbTensor.desc.shape.dims[1] = atbTensor.desc.shape.dims[1] / headDim; // 1: aclnn n dim, 1: atb nd dim, nd / d
93	            atbTensor.desc.shape.dims[0] = atbTensor.desc.shape.dims[0]; // 1: bs dim
94	        } else {
95	            atbTensor.desc.shape.dims[DIM_N] = atbTensor.desc.shape.dims[DIM_N] * atbTensor.desc.shape.dims[DIM_D] / headDim;
96	            atbTensor.desc.shape.dims[DIM_D] = headDim;
97	        }
98	        aclnnTensorPtr->atbTensor = atbTensor;
99	        aclnnTensorPtr->strides = GetCopyTensorStride(atbTensor.desc.shape);
100	        ret = CallAclCreateTensor(atbTensor.desc.shape, atbTensor.desc.shape, atbTensor, aclnnTensorPtr,
101	                                      atbTensor.desc.dtype);
102	        if (ret != NO_ERROR) {
103	            ATB_LOG(ERROR) << GetLogPrefix() << "create aclTensor by aclCreateTensor failed!";
104	            return ret;
105	        }
106	        aclnnTensorPtr->tensorIdx = static_cast<int>(i);
107	        aclnnTensorPtr->needUpdateTensorDataPtr = false;
108	        this->aclnnVariantPack_.aclInTensors.at(i) = aclnnTensorPtr;
109	    }
110	    //cos sin reshape
111	    for (size_t i = ROPE_IN_NUM - COS_SIN_NUM; i < ROPE_IN_NUM; ++i) {
112	        ATB_LOG(INFO) << GetLogPrefix() << "RopeAclnnRunner::BuildAclnnVariantPack inTensor index: " << i;
113	        std::shared_ptr<AclNNTensor> aclnnTensorPtr = std::make_shared<AclNNTensor>();
114	        atb::Tensor atbTensor = runnerVariantPack.inTensors.at(i);
115	        if (!isBSND4D) {
116	            // tnd: [bs, 1*d] -> [bs, 1, d]
117	            atbTensor.desc.shape.dimNum = ACLNN_TND_DIM_NUM;
118	            atbTensor.desc.shape.dims[2] = atbTensor.desc.shape.dims[1]; // 2: aclnn d dim, 1: atb nd dim
119	            atbTensor.desc.shape.dims[1] = DIM_ONE; // 1: aclnn n dim
120	        } else {
121	            atbTensor.desc.shape.dimNum = ACLNN_BSND_DIM_NUM;
122	            Dims qDims = runnerVariantPack.inTensors.at(0).desc.shape;
123	            atbTensor.desc.shape.dims[DIM_D] = headDim; // 3: aclnn d dim
124	            atbTensor.desc.shape.dims[DIM_N] = DIM_ONE; // 2: aclnn n dim
125	            atbTensor.desc.shape.dims[DIM_S] = qDims.dims[DIM_S];
126	            atbTensor.desc.shape.dims[DIM_B] = qDims.dims[DIM_B];
127	        }
128	        aclnnTensorPtr->atbTensor = atbTensor;
129	        aclnnTensorPtr->strides = GetCopyTensorStride(atbTensor.desc.shape);
130	        ret = CallAclCreateTensor(atbTensor.desc.shape, atbTensor.desc.shape, atbTensor, aclnnTensorPtr,
131	                                      atbTensor.desc.dtype);
132	        if (ret != NO_ERROR) {
133	            ATB_LOG(ERROR) << GetLogPrefix() << "create aclTensor by aclCreateTensor failed!";
134	            return ret;
135	        }
136	        aclnnTensorPtr->tensorIdx = static_cast<int>(i);
137	        aclnnTensorPtr->needUpdateTensorDataPtr = false;
138	        this->aclnnVariantPack_.aclInTensors.at(i) = aclnnTensorPtr;
139	    }
140	    //create output
141	    for (size_t i = 0; i < ROPE_OUT_NUM; ++i) {
142	        ATB_LOG(INFO) << GetLogPrefix() << "RopeAclnnRunner::BuildAclnnVariantPack outTensor index: " << i;
143	        std::shared_ptr<AclNNTensor> aclnnTensorPtr = std::make_shared<AclNNTensor>();
144	        atb::Tensor atbTensor = this->aclnnVariantPack_.aclInTensors.at(i)->atbTensor;
145	        atbTensor.deviceData = runnerVariantPack.outTensors.at(i).deviceData;
146	        auto memRet = aclrtMemcpy(atbTensor.deviceData, atbTensor.dataSize,
147	                    this->aclnnVariantPack_.aclInTensors.at(i)->atbTensor.deviceData, atbTensor.dataSize, ACL_MEMCPY_DEVICE_TO_DEVICE);
148	        if (memRet != ACL_SUCCESS) {
149	            return ERROR_CANN_ERROR;
150	        }
151	        aclnnTensorPtr->atbTensor = atbTensor;
152	        aclnnTensorPtr->strides = GetCopyTensorStride(atbTensor.desc.shape);
153	        ret = CallAclCreateTensor(atbTensor.desc.shape, atbTensor.desc.shape, atbTensor, aclnnTensorPtr,
154	                                      atbTensor.desc.dtype);
155	        if (ret != NO_ERROR) {
156	            ATB_LOG(ERROR) << GetLogPrefix() << "create aclTensor by aclCreateTensor failed!";
157	            return ret;
158	        }
159	        aclnnTensorPtr->tensorIdx = static_cast<int>(i);
160	        aclnnTensorPtr->needUpdateTensorDataPtr = false;
161	        this->aclnnVariantPack_.aclOutTensors.at(i) = aclnnTensorPtr;
162	    }
163	    return NO_ERROR;
164	}
165	
166	Status RopeAclnnRunner::LaunchAclnnKernel()
167	{
168	    ATB_LOG(INFO) << GetLogPrefix() << "LaunchAclnnKernel execute start.";
169	    aclrtStream executeStream = GetExecuteStream(this->atbVariantPack_.context);
170	    aclnnStatus ret = RopeAclnnRunner::aclnnExecuteFunc_(this->atbVariantPack_.workspaceBuffer,
171	                                                                  this->atbVariantPack_.workspaceBufferSize,
172	                                                                  this->aclnnExecutor_.get(), executeStream);
173	    if (ret != ACL_SUCCESS) {
174	        ATB_LOG(ERROR) << GetLogPrefix() << "Atb aclnn op kernel launch failed with return value: " << ret;
175	        return ERROR_CANN_ERROR;
176	    }
177	    ATB_LOG(INFO) << GetLogPrefix() << "LaunchAclnnKernel execute success.";
178	    return NO_ERROR;
179	}
180	
181	aclnnStatus RopeAclnnRunner::SetAclNNWorkspaceExecutor()
182	{
183	    ATB_LOG(INFO) << GetLogPrefix() << "aclnn rope setup start.";
184	    ATB_LOG(INFO) << GetLogPrefix() << ", aclInTensors size: " << this->aclnnVariantPack_.aclInTensors.size()
185	                  << ", aclOutTensors size: " << this->aclnnVariantPack_.aclOutTensors.size();
186	    aclTensor *queryRef = aclnnVariantPack_.aclOutTensors.at(ROPE_QUERY_INDEX)->tensor;
187	    aclTensor *keyRef = aclnnVariantPack_.aclOutTensors.at(ROPE_KEY_INDEX)->tensor;
188	    aclTensor *cos = aclnnVariantPack_.aclInTensors.at(ROPE_COS_INDEX)->tensor;
189	    aclTensor *sin = aclnnVariantPack_.aclInTensors.at(ROPE_SIN_INDEX)->tensor;
190	    aclOpExecutor *rawExecutorPtr = this->aclnnExecutor_.get();
191	    ATB_LOG(INFO) << GetLogPrefix() << "&(this->aclnnExecutor_): " << &(this->aclnnExecutor_)
192	#ifdef _DEBUG
193	                  << ", addr of this->aclnnExecutor_: " << this->aclnnExecutor_
194	                  << ", raw ptr from it: " << rawExecutorPtr
195	#endif
196	                  << ", addr of this->aclnnExecutor_: " << this->aclnnExecutor_
197	                  << ", raw ptr from it: " << rawExecutorPtr
198	                  << ", then take the address of the raw ptr: " << &rawExecutorPtr;
199	    ATB_LOG(INFO) << GetLogPrefix() << "workspaceSize addr: " << &(this->atbVariantPack_.workspaceBufferSize);
200	
201	    for (size_t i = 0; i < aclnnVariantPack_.aclInTensors.size(); ++i) {
202	        ATB_LOG(INFO) << GetLogPrefix() << "index " << i << TensorUtil::TensorToString(aclnnVariantPack_.aclInTensors.at(i)->atbTensor);
203	    }
204	    std::string rotaryMode = "half";
205	    if (param_.rotaryCoeff == ROTARY_COEFF_HALF) {
206	        rotaryMode = "half";
207	    } else if (param_.rotaryCoeff == ROTARY_COEFF_QUARTER) {
208	        rotaryMode = "quarter";
209	    } else {
210	        rotaryMode = "interleave";
211	    }
212	    // 4d -> bsnd, 2d -> tnd
213	    RotaryLayout layout = RotaryLayout::BSND;
214	    if (aclnnVariantPack_.aclInTensors.at(ROPE_QUERY_INDEX)->atbTensor.desc.shape.dimNum == ACLNN_TND_DIM_NUM) {
215	        layout = RotaryLayout::TND;
216	    }
217	    ATB_LOG(INFO) << GetLogPrefix() << "layout: " << static_cast<int64_t>(layout);
218	    aclnnStatus ret = RopeAclnnRunner::aclnnGetWorkspaceSizeFunc_(
219	        queryRef,
220	        keyRef,
221	        cos,
222	        sin,
223	        static_cast<int64_t>(layout),
224	        (char *)rotaryMode.c_str(),
225	        &(this->atbVariantPack_.workspaceBufferSize),
226	        &rawExecutorPtr
227	    );
228	    this->aclnnExecutor_ = std::shared_ptr<aclOpExecutor>(rawExecutorPtr, [this](aclOpExecutor *ptr) {
229	        if (ptr && this->executorRepeatable_) { // 可复用时才手动销毁aclOpExecutor
230	            aclDestroyAclOpExecutor(ptr);
231	        }
232	    });
233	    ATB_LOG(INFO) << GetLogPrefix() << "workspaceSize: " << this->atbVariantPack_.workspaceBufferSize;
234	    return ret;
235	}
236	
237	REG_RUNNER_TYPE(RopeAclnnRunner);
238	} // namespace atb
239

